solution.dot_dsl.zig:
const std = @import("std");

pub const Attribute = struct { key: []const u8, value: []const u8 };
pub const Node = struct { name: []const u8, attrs: []const Attribute };
pub const Edge = struct { src: []const u8, dst: []const u8, attrs: []const Attribute };
/// Raw DSL tuples use a numeric tag followed by strings or an attribute map.
pub const Value = union(enum) { tag: i32, text: []const u8, attrs: []const Attribute };
pub const NODE: i32 = 0;
pub const EDGE: i32 = 1;
pub const ATTR: i32 = 2;
pub const Graph = struct {
    nodes: std.array_list.Managed(Node),
    edges: std.array_list.Managed(Edge),
    attrs: std.array_list.Managed(Attribute),
    pub fn init(allocator: std.mem.Allocator, data: ?[]const []const Value) !Graph {
        var graph = Graph{ .nodes = std.array_list.Managed(Node).init(allocator), .edges = std.array_list.Managed(Edge).init(allocator), .attrs = std.array_list.Managed(Attribute).init(allocator) };
        errdefer graph.deinit();
        for (data orelse &.{}) |item| {
            if (item.len < 3) return error.GraphItemIncomplete;
            const kind = switch (item[0]) {
                .tag => |tag| tag,
                else => return error.UnknownItem,
            };
            switch (kind) {
                NODE => {
                    if (item.len != 3) return error.MalformedNode;
                    const name = switch (item[1]) {
                        .text => |v| v,
                        else => return error.MalformedNode,
                    };
                    const attrs = switch (item[2]) {
                        .attrs => |v| v,
                        else => return error.MalformedNode,
                    };
                    try graph.nodes.append(.{ .name = name, .attrs = attrs });
                },
                EDGE => {
                    if (item.len != 4) return error.MalformedEdge;
                    const src = switch (item[1]) {
                        .text => |v| v,
                        else => return error.MalformedEdge,
                    };
                    const dst = switch (item[2]) {
                        .text => |v| v,
                        else => return error.MalformedEdge,
                    };
                    const attrs = switch (item[3]) {
                        .attrs => |v| v,
                        else => return error.MalformedEdge,
                    };
                    try graph.edges.append(.{ .src = src, .dst = dst, .attrs = attrs });
                },
                ATTR => {
                    if (item.len != 3) return error.MalformedAttribute;
                    const key = switch (item[1]) {
                        .text => |v| v,
                        else => return error.MalformedAttribute,
                    };
                    const value = switch (item[2]) {
                        .text => |v| v,
                        else => return error.MalformedAttribute,
                    };
                    var found = false;
                    for (graph.attrs.items) |*attr| if (std.mem.eql(u8, attr.key, key)) {
                        attr.value = value;
                        found = true;
                        break;
                    };
                    if (!found) try graph.attrs.append(.{ .key = key, .value = value });
                },
                else => return error.UnknownItem,
            }
        }
        return graph;
    }
    pub fn deinit(self: *Graph) void {
        self.nodes.deinit();
        self.edges.deinit();
        self.attrs.deinit();
    }
};

tests.test_dot_dsl.zig:
const std = @import("std");
const t = std.testing;
const a = t.allocator;
const m = @import("dot_dsl.zig");

test "empty graph, nodes, edges, attributes and replacing an attribute" {
    var empty = try m.Graph.init(a, null);
    defer empty.deinit();
    try t.expectEqual(@as(usize, 0), empty.nodes.items.len);
    const green = [_]m.Attribute{.{ .key = "color", .value = "green" }};
    const data = [_][]const m.Value{
        &.{ .{ .tag = m.ATTR }, .{ .text = "title" }, .{ .text = "old" } },
        &.{ .{ .tag = m.NODE }, .{ .text = "a" }, .{ .attrs = &green } },
        &.{ .{ .tag = m.NODE }, .{ .text = "b" }, .{ .attrs = &.{} } },
        &.{ .{ .tag = m.EDGE }, .{ .text = "a" }, .{ .text = "b" }, .{ .attrs = &green } },
        &.{ .{ .tag = m.ATTR }, .{ .text = "title" }, .{ .text = "new" } },
    };
    var graph = try m.Graph.init(a, &data);
    defer graph.deinit();
    try t.expectEqual(@as(usize, 2), graph.nodes.items.len);
    try t.expectEqualStrings("a", graph.nodes.items[0].name);
    try t.expectEqualStrings("green", graph.nodes.items[0].attrs[0].value);
    try t.expectEqual(@as(usize, 1), graph.edges.items.len);
    try t.expectEqualStrings("b", graph.edges.items[0].dst);
    try t.expectEqual(@as(usize, 1), graph.attrs.items.len);
    try t.expectEqualStrings("new", graph.attrs.items[0].value);
}
test "all malformed tuple forms and unknown tags" {
    try t.expectError(error.GraphItemIncomplete, m.Graph.init(a, &.{&.{}}));
    try t.expectError(error.MalformedNode, m.Graph.init(a, &.{&.{ .{ .tag = m.NODE }, .{ .text = "a" }, .{ .attrs = &.{} }, .{ .text = "extra" } }}));
    try t.expectError(error.MalformedEdge, m.Graph.init(a, &.{&.{ .{ .tag = m.EDGE }, .{ .text = "a" }, .{ .text = "b" } }}));
    try t.expectError(error.MalformedAttribute, m.Graph.init(a, &.{&.{ .{ .tag = m.ATTR }, .{ .text = "a" }, .{ .text = "b" }, .{ .text = "extra" } }}));
    try t.expectError(error.UnknownItem, m.Graph.init(a, &.{&.{ .{ .tag = 99 }, .{ .text = "a" }, .{ .text = "b" } }}));
}
